        full = os.path.join(box, path)
        t = ent.get("t", "f")
        if t == "h":
            later.append((full, ent))
            continue
        if t == "d":
            os.makedirs(full, exist_ok=True)
        elif t == "l":
            os.makedirs(os.path.dirname(full), exist_ok=True)
            os.symlink(ent["to"], full)
        else:
            os.makedirs(os.path.dirname(full), exist_ok=True)
